void tg3_get_vpd_info(struct tg3 *tp) {
    u8 *vpd_data = NULL;
    u32 len = 0;
    u32 man_id_start = 0, ven_id_start = 0;
    u32 i;

    vpd_data = kmalloc(TG3_VPD_LEN, GFP_KERNEL);
    if (!vpd_data)
        goto skip_vpd;

    if (pci_read_vpd(tp->pdev, 0, TG3_VPD_LEN, vpd_data) != TG3_VPD_LEN)
        goto skip_vpd;

    for (i = 0; i < len; i++) {
        if (strncmp(&vpd_data[i], "MANID", 5) == 0) {
            man_id_start = i + 5;
            break;
        }
    }

    for (i = 0; i < len; i++) {
        if (strncmp(&vpd_data[i], "VENID", 5) == 0) {
            ven_id_start = i + 5;
            break;
        }
    }

    if (man_id_start && ven_id_start) {
        char fw_version[32], part_number[32];

        memset(fw_version, 0, sizeof(fw_version));
        memset(part_number, 0, sizeof(part_number));

        strncpy(fw_version, &vpd_data[man_id_start], sizeof(fw_version) - 1);
        strncpy(part_number, &vpd_data[ven_id_start], sizeof(part_number) - 1);

        strlcpy(tp->fw_version, fw_version, sizeof(tp->fw_version));
        strlcpy(tp->part_number, part_number, sizeof(tp->part_number));
    } else {
        if (tp->asic_rev == ASIC_REV_5755 || tp->asic_rev == ASIC_REV_5787) {
            snprintf(tp->fw_version, sizeof(tp->fw_version),
                     "%d.%02d", tp->phy_revision >> 4, tp->phy_revision & 0x0f);
        } else {
            snprintf(tp->fw_version, sizeof(tp->fw_version),
                     "%d.%02d", tp->phy_revision >> 8, tp->phy_revision & 0xff);
        }

        switch (tp->pci_chip_rev_id) {
        case CHIPREV_ID_5703_A0:
            snprintf(tp->part_number, sizeof(tp->part_number), "BCM5703 A0");
            break;
        case CHIPREV_ID_5703_A1:
            snprintf(tp->part_number, sizeof(tp->part_number), "BCM5703 A1");
            break;
        case CHIPREV_ID_5703_B0:
            snprintf(tp->part_number, sizeof(tp->part_number), "BCM5703 B0");
            break;
        default:
            snprintf(tp->part_number, sizeof(tp->part_number), "Unknown");
            break;
        }
    }

skip_vpd:
    kfree(vpd_data);
}

static void tg3_read_vpd(struct tg3 *tp)
{
    u32 vpd_data[4];
    u32 val;
    int i, len;
    char *buf, *p;

    /* Try to read VPD data */
    if (tg3_nvram_read(tp, 0x100, vpd_data, 4 * sizeof(u32)))
        return;

    /* Search for manufacturer ID and vendor information */
    for (i = 0; i < 4; i++) {
        if (vpd_data[i] == 0x12345678) {
            buf = kmalloc(128, GFP_KERNEL);
            if (!buf)
                return;

            len = 0;
            p = buf;
            while (len < 128) {
                val = tg3_nvram_read(tp, 0x100 + (i + len + 1) * sizeof(u32), NULL, 0);
                if (val == -1)
                    break;

                if (val == 0x7FFFFFFF)
                    break;

                *p++ = (val >> 24) & 0xFF;
                *p++ = (val >> 16) & 0xFF;
                *p++ = (val >> 8) & 0xFF;
                *p++ = val & 0xFF;
                len += 4;
            }

            *p = '\0';
            if (sscanf(buf, "Manufacturer ID: %s Vendor: %s", tp->fw_version, tp->board_part_number) == 2) {
                if (strlen(tp->fw_version) > 31)
                    tp->fw_version[31] = '\0';
                if (strlen(tp->board_part_number) > 31)
                    tp->board_part_number[31] = '\0';
            } else {
                /* Fallback to predefined values based on ASIC revision and device type */
                snprintf(tp->fw_version, 32, "%x.%02x",
                         (tp->pci_chip_rev_id >> 4) & 0xf,
                         tp->pci_chip_rev_id & 0xf);
                snprintf(tp->board_part_number, 32, "BCM%x-1GC",
                         tp->pci_dev->device);
            }

            kfree(buf);
            return;
        }
    }

    /* Fallback to predefined values based on ASIC revision and device type */
    snprintf(tp->fw_version, 32, "%x.%02x",
             (tp->pci_chip_rev_id >> 4) & 0xf,
             tp->pci_chip_rev_id & 0xf);
    snprintf(tp->board_part_number, 32, "BCM%x-1GC",
             tp->pci_dev->device);
}

void tg3_read_vpd(struct tg3 *tp) {
    u8 *vpd_data;
    u32 vpd_len;
    char *fw_version = "unknown";
    char *part_number = "unknown";
    int i;

    if (tp->vpd_size == 0) {
        goto use_defaults;
    }

    vpd_data = kmalloc(tp->vpd_size, GFP_KERNEL);
    if (!vpd_data)
        return;

    if (tg3_read_vpd_block(tp, vpd_data, tp->vpd_size) != 0)
        goto free_vpd;

    for (i = 0; i < tp->vpd_size; i++) {
        if (strncmp(&vpd_data[i], "MANUFACTURER ID", 15) == 0) {
            fw_version = &vpd_data[i + 16];
            break;
        }
    }

    for (i = 0; i < tp->vpd_size; i++) {
        if (strncmp(&vpd_data[i], "VENDOR", 6) == 0) {
            part_number = &vpd_data[i + 7];
            break;
        }
    }

free_vpd:
    kfree(vpd_data);

use_defaults:
    strncpy(tp->fw_version, fw_version, sizeof(tp->fw_version) - 1);
    strncpy(tp->board_part_number, part_number, sizeof(tp->board_part_number) - 1);
}

void tg3_read_vpd_info(struct tg3 *tp)
{
    u8 *vpd_block;
    u8 *p;
    int vpd_size = 512;
    int i;
    u16 val;
    const u8 *fw_ver;
    const u8 *board_part;
    char *buf;
    char *end;
    int len;

    vpd_block = kmalloc(vpd_size, GFP_KERNEL);
    if (!vpd_block)
        goto out;

    if (pci_read_vpd(tp->pdev, 0, vpd_size, vpd_block)) {
        kfree(vpd_block);
        goto out;
    }

    p = vpd_block;
    while (p < vpd_block + vpd_size) {
        if (*p == 0xff)
            break;
        if (strncmp(p, "MANUFACTURER ID", strlen("MANUFACTURER ID")) == 0) {
            fw_ver = p + strlen("MANUFACTURER ID");
            break;
        }
        p++;
    }

    if (!fw_ver || *fw_ver == 0xff) {
        fw_ver = NULL;
        goto out_no_keywords;
    }

    p = vpd_block;
    while (p < vpd_block + vpd_size) {
        if (*p == 0xff)
            break;
        if (strncmp(p, "VENDOR", strlen("VENDOR")) == 0) {
            board_part = p + strlen("VENDOR");
            break;
        }
        p++;
    }

    if (!board_part || *board_part == 0xff)
        board_part = NULL;

    if (!fw_ver && !board_part) {
        kfree(vpd_block);
        goto out;
    }

    if (!fw_ver) {
        kfree(vpd_block);
        goto out;
    }

    if (fw_ver) {
        buf = tp->fw_ver;
        end = buf + sizeof(tp->fw_ver) - 1;
        for (i = 0; *fw_ver && fw_ver < vpd_block + vpd_size && buf < end; i++, fw_ver++)
            *buf++ = *fw_ver;
        *buf = '\0';
    }

    if (board_part) {
        buf = tp->board_part_num;
        end = buf + sizeof(tp->board_part_num) - 1;
        for (i = 0; *board_part && board_part < vpd_block + vpd_size && buf < end; i++, board_part++)
            *buf++ = *board_part;
        *buf = '\0';
    }

    kfree(vpd_block);
    return;

out_no_keywords:
    kfree(vpd_block);
out:
    val = tr32(TG3_CHIP_REVISION);

    switch (val & TG3_CHIPREV_MASK) {
    case TG3_CHIPREV_5700:
        strcpy(tp->board_part_num, "BCM5700");
        break;
    case TG3_CHIPREV_5701:
        strcpy(tp->board_part_num, "BCM5701");
        break;
    case TG3_CHIPREV_5703:
        strcpy(tp->board_part_num, "BCM5703");
        break;
    case TG3_CHIPREV_5704:
        strcpy(tp->board_part_num, "BCM5704");
        break;
    case TG3_CHIPREV_5705:
        strcpy(tp->board_part_num, "BCM5705");
        break;
    case TG3_CHIPREV_5706:
        strcpy(tp->board_part_num, "BCM5706");
        break;
    case TG3_CHIPREV_5714:
        strcpy(tp->board_part_num, "BCM5714");
        break;
    case TG3_CHIPREV_5715:
        strcpy(tp->board_part_num, "BCM5715");
        break;
    case TG3_CHIPREV_5716:
        strcpy(tp->board_part_num, "BCM5716");
        break;
    case TG3_CHIPREV_5717:
        strcpy(tp->board_part_num, "BCM5717");
        break;
    default:
        strcpy(tp->board_part_num, "Unknown");
        break;
    }

    tp->fw_ver[0] = '0';
    tp->fw_ver[1] = '.';
    tp->fw_ver[2] = '0';
    tp->fw_ver[3] = '\0';
}

void tg3_read_vpd(struct tg3 *tp)
{
    u8 vpd_data[256];
    u16 val;
    int i, j, len;
    char *fw_version = NULL;
    char *part_number = NULL;

    /* Read VPD data block */
    if (!tg3_read_vpd_block(tp, vpd_data, sizeof(vpd_data)))
        goto fallback;

    /* Search for "Firmware Version" and "Board Part Number" */
    for (i = 0; i < sizeof(vpd_data); i++) {
        if (vpd_data[i] == 'F' && i + 16 < sizeof(vpd_data)) {
            if (strncmp(&vpd_data[i], "Firmware Version", 16) == 0) {
                fw_version = &vpd_data[i + 16];
                break;
            }
        }
        if (vpd_data[i] == 'B' && i + 14 < sizeof(vpd_data)) {
            if (strncmp(&vpd_data[i], "Board Part Number", 14) == 0) {
                part_number = &vpd_data[i + 14];
                break;
            }
        }
    }

    if (fw_version) {
        len = 0;
        while (len < TG3_FW_VER_LEN - 1 && fw_version[len] != '\0' && fw_version[len] != ' ' && fw_version[len] != '\n')
            len++;
        strncpy(tp->fw_version, fw_version, len);
        tp->fw_version[len] = '\0';
    }

    if (part_number) {
        len = 0;
        while (len < TG3_BOARD_PARTNO_LEN - 1 && part_number[len] != '\0' && part_number[len] != ' ' && part_number[len] != '\n')
            len++;
        strncpy(tp->board_partno, part_number, len);
        tp->board_partno[len] = '\0';
    } else {
fallback:
        val = tg3_read_asic_rev(tp);
        switch (val) {
        case ASIC_REV_5700:
            snprintf(tp->board_partno, TG3_BOARD_PARTNO_LEN, "BCM5700");
            break;
        case ASIC_REV_5701:
            snprintf(tp->board_partno, TG3_BOARD_PARTNO_LEN, "BCM5701");
            break;
        case ASIC_REV_5703:
            snprintf(tp->board_partno, TG3_BOARD_PARTNO_LEN, "BCM5703");
            break;
        default:
            snprintf(tp->board_partno, TG3_BOARD_PARTNO_LEN, "Unknown");
            break;
        }
    }
}
